// ObjectFormatSHA1 is the object format a server uses when it advertises
// none. Git only began advertising object-format with SHA256 support.
const ObjectFormatSHA1 = "sha1"

// ObjectFormat returns the object format the source advertised.
func (s *RefService) ObjectFormat() string {
	if s == nil {
		return ObjectFormatSHA1
	}
	if s.Protocol == "v2" {
		if v := s.V2Caps.Value(string(capability.ObjectFormat)); v != "" {
			return v
		}
		return ObjectFormatSHA1
	}
	return AdvObjectFormat(s.V1Adv)
}

// AdvObjectFormat returns the object format a v1 advertisement names.
func AdvObjectFormat(adv *packp.AdvRefs) string {
	if adv == nil {
		return ObjectFormatSHA1
	}
	if vals := adv.Capabilities.Get(capability.ObjectFormat); len(vals) > 0 && vals[0] != "" {
		return vals[0]
	}
	return ObjectFormatSHA1
}
