package translate

import (
	"bytes"
	"errors"
	"fmt"
	"sort"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
)

// NoteEntry is one note in a git notes tree: the annotated object and the
// blob holding its note.
type NoteEntry struct {
	Object plumbing.Hash
	Blob   plumbing.Hash
}

// ReadHashNotes reads a notes ref whose notes each hold one object hash, as
// convert-sha256's refs/notes/sha1-origin does. It returns the annotated
// object to noted hash mapping and the tree entries it came from, so a
// caller can extend the notes without reading every blob again.
//
// Both flat trees and fanout trees (annotated hashes split across nested
// directories) are read.
func ReadHashNotes(store storer.EncodedObjectStorer, commit plumbing.Hash) (map[plumbing.Hash]plumbing.Hash, []NoteEntry, error) {
	c, err := object.GetCommit(store, commit)
	if err != nil {
		return nil, nil, fmt.Errorf("load notes commit %s: %w", commit, err)
	}
	tree, err := object.GetTree(store, c.TreeHash)
	if err != nil {
		return nil, nil, fmt.Errorf("load notes tree %s: %w", c.TreeHash, err)
	}
	values := make(map[plumbing.Hash]plumbing.Hash)
	var entries []NoteEntry
	if err := readNotesTree(store, tree, "", values, &entries); err != nil {
		return nil, nil, err
	}
	return values, entries, nil
}

func readNotesTree(store storer.EncodedObjectStorer, tree *object.Tree, prefix string, values map[plumbing.Hash]plumbing.Hash, entries *[]NoteEntry) error {
	for _, e := range tree.Entries {
		name := prefix + e.Name
		if e.Mode == filemode.Dir {
			sub, err := object.GetTree(store, e.Hash)
			if err != nil {
				return fmt.Errorf("load notes subtree %s: %w", name, err)
			}
			if err := readNotesTree(store, sub, name, values, entries); err != nil {
				return err
			}
			continue
		}
		annotated, ok := plumbing.FromHex(name)
		if !ok {
			// Not a note: git notes trees may carry other files.
			continue
		}
		blob, err := object.GetBlob(store, e.Hash)
		if err != nil {
			return fmt.Errorf("load note for %s: %w", name, err)
		}
		content, err := readAll(blob)
		if err != nil {
			return fmt.Errorf("read note for %s: %w", name, err)
		}
		fields := bytes.Fields(content)
		if len(fields) == 0 {
			return fmt.Errorf("note for %s is empty", name)
		}
		noted, ok := plumbing.FromHex(string(fields[0]))
		if !ok {
			return fmt.Errorf("note for %s does not hold an object hash", name)
		}
		values[annotated] = noted
		*entries = append(*entries, NoteEntry{Object: annotated, Blob: e.Hash})
	}
	return nil
}

// WriteHashNotes writes a notes commit holding existing plus one note per
// pair in add, keyed by Pair.Target and holding Pair.Source. The tree is
// flat. parent is the previous notes commit, or zero for the first one. It
// returns the new commit and every object it wrote, which are the objects a
// push of the notes ref must send.
func WriteHashNotes(store storer.EncodedObjectStorer, parent plumbing.Hash, existing []NoteEntry, add []Pair, sig object.Signature, message string) (plumbing.Hash, []plumbing.Hash, error) {
	if len(add) == 0 {
		return plumbing.ZeroHash, nil, errors.New("no notes to add")
	}
	byName := make(map[string]plumbing.Hash, len(existing)+len(add))
	for _, e := range existing {
		byName[e.Object.String()] = e.Blob
	}
	written := make([]plumbing.Hash, 0, len(add)+2)
	for _, p := range add {
		blob, err := storeObject(store, plumbing.BlobObject, func(w *bytes.Buffer) error {
			_, err := w.WriteString(p.Source.String() + "\n")
			return err
		})
		if err != nil {
			return plumbing.ZeroHash, nil, fmt.Errorf("store note for %s: %w", p.Target, err)
		}
		byName[p.Target.String()] = blob
		written = append(written, blob)
	}

	tree := &object.Tree{Entries: make([]object.TreeEntry, 0, len(byName))}
	for name, blob := range byName {
		tree.Entries = append(tree.Entries, object.TreeEntry{Name: name, Mode: filemode.Regular, Hash: blob})
	}
	sort.Slice(tree.Entries, func(i, j int) bool { return tree.Entries[i].Name < tree.Entries[j].Name })
	treeHash, err := encodeObject(store, tree.Encode)
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("store notes tree: %w", err)
	}
	written = append(written, treeHash)

	commit := &object.Commit{Author: sig, Committer: sig, Message: message, TreeHash: treeHash}
	if !parent.IsZero() {
		commit.ParentHashes = []plumbing.Hash{parent}
	}
	commitHash, err := encodeObject(store, commit.Encode)
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("store notes commit: %w", err)
	}
	written = append(written, commitHash)
	return commitHash, written, nil
}

func encodeObject(store storer.EncodedObjectStorer, encode func(plumbing.EncodedObject) error) (plumbing.Hash, error) {
	obj := store.NewEncodedObject()
	if err := encode(obj); err != nil {
		return plumbing.ZeroHash, err
	}
	return store.SetEncodedObject(obj)
}

func storeObject(store storer.EncodedObjectStorer, typ plumbing.ObjectType, fill func(*bytes.Buffer) error) (plumbing.Hash, error) {
	var buf bytes.Buffer
	if err := fill(&buf); err != nil {
		return plumbing.ZeroHash, err
	}
	t := &Translator{dst: store}
	return t.store(typ, buf.Bytes())
}

package translate

import (
	"maps"
	"strings"
	"testing"
	"time"

	"github.com/go-git/go-git/v6/plumbing"
	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

func TestHashNotes_RoundTripAndExtend(t *testing.T) {
	t.Parallel()

	store := memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA1))
	sig := object.Signature{Name: "git-sync", Email: "git-sync@example.com", When: time.Unix(0, 0).UTC()}
	sha1A := plumbing.NewHash(strings.Repeat("a1", 20))
	sha1B := plumbing.NewHash(strings.Repeat("b1", 20))
	sha256A := plumbing.NewHash(strings.Repeat("a2", 32))
	sha256B := plumbing.NewHash(strings.Repeat("b2", 32))

	first, written, err := WriteHashNotes(store, plumbing.ZeroHash, nil, []Pair{{Source: sha256A, Target: sha1A}}, sig, "notes\n")
	if err != nil {
		t.Fatal(err)
	}
	if len(written) != 3 || written[2] != first {
		t.Fatalf("written objects: got %v, want blob, tree, commit %s", written, first)
	}
	values, entries, err := ReadHashNotes(store, first)
	if err != nil {
		t.Fatal(err)
	}
	if want := map[plumbing.Hash]plumbing.Hash{sha1A: sha256A}; !maps.Equal(values, want) {
		t.Fatalf("first notes: got %v, want %v", values, want)
	}

	second, _, err := WriteHashNotes(store, first, entries, []Pair{{Source: sha256B, Target: sha1B}}, sig, "notes\n")
	if err != nil {
		t.Fatal(err)
	}
	values, _, err = ReadHashNotes(store, second)
	if err != nil {
		t.Fatal(err)
	}
	if want := map[plumbing.Hash]plumbing.Hash{sha1A: sha256A, sha1B: sha256B}; !maps.Equal(values, want) {
		t.Fatalf("extended notes: got %v, want %v", values, want)
	}
	c, err := object.GetCommit(store, second)
	if err != nil {
		t.Fatal(err)
	}
	if len(c.ParentHashes) != 1 || c.ParentHashes[0] != first {
		t.Errorf("notes commit parents: got %v, want [%s]", c.ParentHashes, first)
	}
}

func TestReadHashNotes_Fanout(t *testing.T) {
	t.Parallel()

	store := memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA1))
	annotated := plumbing.NewHash(strings.Repeat("c3", 20))
	noted := plumbing.NewHash(strings.Repeat("d4", 32))
	blob := writeRaw(t, store, plumbing.BlobObject, noted.String()+"\n")
	sub := writeTreeEntries(t, store, []treeEntry{{"100644", annotated.String()[2:], blob}})
	root := writeTreeEntries(t, store, []treeEntry{{"40000", annotated.String()[:2], sub}})
	commit := writeRaw(t, store, plumbing.CommitObject, "tree "+root.String()+"\n"+
		"author A <a@example.com> 0 +0000\ncommitter A <a@example.com> 0 +0000\n\nnotes\n")

	values, _, err := ReadHashNotes(store, commit)
	if err != nil {
		t.Fatal(err)
	}
	if got := values[annotated]; got != noted {
		t.Fatalf("fanout note for %s: got %s, want %s", annotated, got, noted)
	}
}

package syncer

import (
	"context"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
	"github.com/go-git/go-git/v6/storage/memory"

	"entire.io/entire/git-sync/internal/convert"
	"entire.io/entire/git-sync/internal/gitproto"
	"entire.io/entire/git-sync/internal/planner"
	"entire.io/entire/git-sync/internal/translate"
)

const (
	// sourceOriginNotesRef is where convert-sha256 records, for each commit
	// it converted, the SHA1 commit it came from.
	sourceOriginNotesRef = plumbing.ReferenceName("refs/notes/sha1-origin")
	// targetOriginNotesRef is where a translated sync records, for each
	// commit it wrote to the SHA1 target, the SHA256 commit it came from.
	targetOriginNotesRef = plumbing.ReferenceName("refs/notes/sha256-origin")
	// convertedTagPrefix holds convert-sha256's attestation tags. They sign
	// the conversion itself and mean nothing on the SHA1 side.
	convertedTagPrefix = "refs/tags/converted/"
)

// translating reports whether the source and target use different object
// formats, so objects must be translated rather than relayed.
func (s *syncSession) translating() bool {
	return s.target != nil && s.sourceService.ObjectFormat() != s.target.objectFormat
}

// validateTranslation rejects what a translated sync does not support. Only
// SHA256 to SHA1 is supported: it is how a SHA1 repository kept as a
// read-only reference follows a SHA256 repository converted from it.
func validateTranslation(cfg Config, sourceFormat, targetFormat string) error {
	if sourceFormat != formatcfg.SHA256.String() || targetFormat != formatcfg.SHA1.String() {
		return fmt.Errorf("source uses %s objects and target uses %s: only a SHA256 source can sync to a SHA1 target "+
			"(use convert-sha256 to move a SHA1 repository to SHA256)", sourceFormat, targetFormat)
	}
	switch {
	case cfg.Mode == modeReplicate:
		return errors.New("replicate does not support a source and target with different object formats; use sync")
	case cfg.ForceAny():
		return errors.New("force flags are not supported when the source and target use different object formats")
	case cfg.Prune:
		return errors.New("--prune is not supported when the source and target use different object formats")
	case cfg.AllRefs:
		return errors.New("--all-refs is not supported when the source and target use different object formats; sync branches and tags")
	}
	return nil
}

// runTranslatedSync syncs a SHA256 source into a SHA1 target.
//
// It fetches the full closure of the desired refs, translates it into SHA1
// objects and pushes what the target lacks. Translation stops at commits
// whose SHA1 counterpart is already recorded: refs/notes/sha1-origin on the
// source covers history from before the conversion, and
// refs/notes/sha256-origin on the target covers commits earlier syncs wrote.
// The recorded hashes win over translating again, because conversion drops
// signatures and rewrites messages, so translating a converted commit back
// does not reproduce the original SHA1 commit. The push updates
// refs/notes/sha256-origin with every commit it translated.
//
// Tags are immutable: a tag the target already has is left alone whatever it
// points at.
func (s *syncSession) runTranslatedSync(ctx context.Context) (Result, error) {
	sourceFormat, targetFormat := s.sourceService.ObjectFormat(), s.target.objectFormat
	if err := validateTranslation(s.cfg, sourceFormat, targetFormat); err != nil {
		return Result{}, err
	}

	desiredRefs, _, err := planner.BuildDesiredRefs(s.sourceRefMap, planConfig(s.cfg))
	if err != nil {
		return Result{}, fmt.Errorf("build desired refs: %w", err)
	}
	for name := range desiredRefs {
		if strings.HasPrefix(name.String(), convertedTagPrefix) {
			delete(desiredRefs, name)
		}
	}
	if len(desiredRefs) == 0 {
		return Result{}, errors.New("no source refs matched")
	}

	sourceStore := newBoundedStorer(memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA256)), effectiveMaxObjects(s.cfg))
	fetch := convert.DesiredRefs(desiredRefs)
	originNotes, err := s.sourceRefHash(ctx, sourceOriginNotesRef)
	if err != nil {
		return Result{}, err
	}
	if !originNotes.IsZero() {
		fetch[sourceOriginNotesRef] = gitproto.DesiredRef{
			SourceRef: sourceOriginNotesRef, TargetRef: sourceOriginNotesRef, SourceHash: originNotes,
		}
	}
	if err := s.sourceService.FetchToStore(ctx, sourceStore, s.sourceConn, fetch, nil); err != nil &&
		!errors.Is(err, git.NoErrAlreadyUpToDate) {
		return Result{}, fmt.Errorf("fetch source objects: %w", err)
	}

	seed := make(map[plumbing.Hash]plumbing.Hash)
	if !originNotes.IsZero() {
		converted, _, err := translate.ReadHashNotes(sourceStore, originNotes)
		if err != nil {
			return Result{}, fmt.Errorf("read %s: %w", sourceOriginNotesRef, err)
		}
		maps_copy(seed, converted)
	}
	targetNotes := s.target.refMap[targetOriginNotesRef]
	var targetNoteEntries []translate.NoteEntry
	if !targetNotes.IsZero() {
		synced, entries, err := s.readTargetNotes(ctx, targetNotes)
		if err != nil {
			return Result{}, err
		}
		for sha1, sha256 := range synced {
			seed[sha256] = sha1
		}
		targetNoteEntries = entries
	}

	outStore := memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA1))
	tr := translate.New(sourceStore, outStore, seed)
	translated := make(map[plumbing.ReferenceName]plumbing.Hash, len(desiredRefs))
	for _, name := range sortedRefNames(desiredRefs) {
		want := desiredRefs[name]
		if want.Kind == planner.RefKindTag && !s.target.refMap[want.TargetRef].IsZero() {
			continue
		}
		out, err := tr.Translate(want.SourceHash)
		if err != nil {
			return Result{}, fmt.Errorf("translate %s: %w", want.SourceRef, err)
		}
		translated[name] = out
	}

	reverse := make(map[plumbing.Hash]plumbing.Hash, len(seed))
	for sha256, sha1 := range seed {
		reverse[sha1] = sha256
	}
	for _, p := range tr.Commits() {
		reverse[p.Target] = p.Source
	}

	plans := make([]BranchPlan, 0, len(desiredRefs))
	for _, name := range sortedRefNames(desiredRefs) {
		plans = append(plans, planTranslatedRef(sourceStore, desiredRefs[name], s.target.refMap[desiredRefs[name].TargetRef], translated[name], reverse))
	}

	result := Result{
		Plans: plans, DryRun: s.cfg.DryRun, OperationMode: modeSync, Protocol: s.sourceService.Protocol,
		RelayReason: "source objects are " + sourceFormat + " and target objects are " + targetFormat + "; translated before push",
		SourceHEAD:  s.sourceService.HeadTarget,
	}
	pushPlans := classifyPlans(plans, s.cfg.DryRun, &result)
	if !s.cfg.DryRun && result.Blocked > 0 {
		return result, fmt.Errorf("blocked %d ref update(s): the target has commits that are not translations of the source's", result.Blocked)
	}
	if n := tr.SignaturesStripped(); n > 0 {
		s.notice(fmt.Sprintf("dropped signatures from %d translated commit(s) and tag(s): they sign %s bytes", n, sourceFormat))
	}

	newCommits := tr.Commits()
	if !s.cfg.DryRun && (len(pushPlans) > 0 || len(newCommits) > 0) {
		if err := s.pushTranslated(ctx, sourceStore, outStore, tr, pushPlans, translated, reverse, targetNotes, targetNoteEntries, newCommits); err != nil {
			return result, err
		}
	}

	s.finalizeCounts(pushPlans, &result)
	result.Stats = s.stats.snapshot()
	result.Measurement = s.measurementDone()
	return result, nil
}

// planTranslatedRef plans one ref. sourceStore holds the source objects,
// targetHash is the target's current value, translated is the source tip
// translated into the target's format (zero for a tag left alone), and
// reverse maps target commits to the source commits they translate.
func planTranslatedRef(
	sourceStore storer.EncodedObjectStorer,
	want planner.DesiredRef,
	targetHash, translated plumbing.Hash,
	reverse map[plumbing.Hash]plumbing.Hash,
) BranchPlan {
	plan := BranchPlan{
		Branch: want.Label, SourceRef: want.SourceRef, TargetRef: want.TargetRef,
		SourceHash: want.SourceHash, TargetHash: targetHash, Kind: want.Kind,
	}
	switch {
	case want.Kind == planner.RefKindTag && !targetHash.IsZero():
		plan.Action = planner.ActionSkip
		plan.Reason = "tag already exists on target"
		return plan
	case targetHash.IsZero():
		plan.Action = planner.ActionCreate
		plan.Reason = "create as " + planner.ShortHash(translated)
		return plan
	case translated == targetHash:
		plan.Action = planner.ActionSkip
		plan.Reason = planner.ShortHash(targetHash) + " already current"
		return plan
	}

	sourceOfTarget, ok := reverse[targetHash]
	if !ok {
		plan.Action = planner.ActionBlock
		plan.Reason = planner.ShortHash(targetHash) + " is not a translation of any source commit; was the target written to directly?"
		return plan
	}
	ancestry, err := planner.CheckAncestry(sourceStore, want.SourceHash, sourceOfTarget)
	switch {
	case err != nil:
		plan.Action = planner.ActionBlock
		plan.Reason = "cannot verify fast-forward: " + err.Error()
	case ancestry == planner.AncestryReachable:
		plan.Action = planner.ActionUpdate
		plan.Reason = planner.ShortHash(targetHash) + " -> " + planner.ShortHash(translated)
	default:
		plan.Action = planner.ActionBlock
		plan.Reason = planner.ShortHash(targetHash) + " (source " + planner.ShortHash(sourceOfTarget) + ") is not an ancestor of " + planner.ShortHash(want.SourceHash)
	}
	return plan
}

func (s *syncSession) pushTranslated(
	ctx context.Context,
	sourceStore storer.EncodedObjectStorer,
	outStore storer.EncodedObjectStorer,
	tr *translate.Translator,
	pushPlans []BranchPlan,
	translated map[plumbing.ReferenceName]plumbing.Hash,
	reverse map[plumbing.Hash]plumbing.Hash,
	targetNotes plumbing.Hash,
	targetNoteEntries []translate.NoteEntry,
	newCommits []translate.Pair,
) error {
	onTarget := make(map[plumbing.Hash]struct{}, len(reverse))
	for _, sha256 := range reverse {
		onTarget[sha256] = struct{}{}
	}
	for _, p := range newCommits {
		// Translated this run, so not on the target unless a ref already
		// points at it, which the loop below handles.
		delete(onTarget, p.Source)
	}
	for _, h := range s.target.refMap {
		if sha256, ok := reverse[h]; ok {
			onTarget[sha256] = struct{}{}
		}
	}

	wants := make([]plumbing.Hash, 0, len(pushPlans))
	cmds := make([]gitproto.PushCommand, 0, len(pushPlans)+1)
	for _, p := range pushPlans {
		wants = append(wants, p.SourceHash)
		cmds = append(cmds, gitproto.PushCommand{Name: p.TargetRef, Old: p.TargetHash, New: translated[p.TargetRef]})
	}
	sourceObjects, err := objectsMissingFromTarget(sourceStore, wants, onTarget)
	if err != nil {
		return fmt.Errorf("compute objects to push: %w", err)
	}
	hashes := make([]plumbing.Hash, 0, len(sourceObjects)+3)
	for _, h := range sourceObjects {
		out, ok := tr.Lookup(h)
		if !ok {
			return fmt.Errorf("object %s to push was never translated", h)
		}
		hashes = append(hashes, out)
	}

	if len(newCommits) > 0 {
		sig := object.Signature{Name: "git-sync", Email: "noreply@entire.io", When: time.Now().UTC()}
		notes, written, err := translate.WriteHashNotes(outStore, targetNotes, targetNoteEntries, newCommits, sig,
			"git-sync: SHA256 origin of translated commits\n")
		if err != nil {
			return fmt.Errorf("write %s: %w", targetOriginNotesRef, err)
		}
		hashes = append(hashes, written...)
		cmds = append(cmds, gitproto.PushCommand{Name: targetOriginNotesRef, Old: targetNotes, New: notes})
	}

	if err := s.target.pusher.PushObjects(ctx, cmds, outStore, hashes); err != nil {
		return fmt.Errorf("push translated objects: %w", err)
	}
	return nil
}

// objectsMissingFromTarget lists the objects reachable from wants that the
// target lacks, given onTarget, the source commits whose translations the
// target holds. The walk stops at those commits, and leaves out every object
// in their trees, which is what a commit built on them shares with them.
func objectsMissingFromTarget(store storer.EncodedObjectStorer, wants []plumbing.Hash, onTarget map[plumbing.Hash]struct{}) ([]plumbing.Hash, error) {
	var boundary []plumbing.Hash
	seen := make(map[plumbing.Hash]struct{})
	var reachable []plumbing.Hash
	stack := slices.Clone(wants)
	for len(stack) > 0 {
		h := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if _, ok := seen[h]; ok {
			continue
		}
		seen[h] = struct{}{}
		if _, ok := onTarget[h]; ok {
			boundary = append(boundary, h)
			continue
		}
		children, err := objectChildren(store, h)
		if err != nil {
			return nil, err
		}
		reachable = append(reachable, h)
		stack = append(stack, children...)
	}

	shared := make(map[plumbing.Hash]struct{})
	for _, c := range boundary {
		commit, err := object.GetCommit(store, c)
		if err != nil {
			if errors.Is(err, plumbing.ErrObjectNotFound) {
				continue
			}
			return nil, fmt.Errorf("load commit %s: %w", c, err)
		}
		if err := collectTree(store, commit.TreeHash, shared); err != nil {
			return nil, err
		}
	}
	out := reachable[:0]
	for _, h := range reachable {
		if _, ok := shared[h]; !ok {
			out = append(out, h)
		}
	}
	return out, nil
}

func objectChildren(store storer.EncodedObjectStorer, h plumbing.Hash) ([]plumbing.Hash, error) {
	obj, err := store.EncodedObject(plumbing.AnyObject, h)
	if err != nil {
		return nil, fmt.Errorf("load object %s: %w", h, err)
	}
	switch obj.Type() {
	case plumbing.CommitObject:
		c, err := object.DecodeCommit(store, obj)
		if err != nil {
			return nil, fmt.Errorf("decode commit %s: %w", h, err)
		}
		return append([]plumbing.Hash{c.TreeHash}, c.ParentHashes...), nil
	case plumbing.TreeObject:
		t, err := object.DecodeTree(store, obj)
		if err != nil {
			return nil, fmt.Errorf("decode tree %s: %w", h, err)
		}
		children := make([]plumbing.Hash, 0, len(t.Entries))
		for _, e := range t.Entries {
			children = append(children, e.Hash)
		}
		return children, nil
	case plumbing.TagObject:
		t, err := object.DecodeTag(store, obj)
		if err != nil {
			return nil, fmt.Errorf("decode tag %s: %w", h, err)
		}
		return []plumbing.Hash{t.Target}, nil
	default:
		return nil, nil
	}
}

func collectTree(store storer.EncodedObjectStorer, h plumbing.Hash, into map[plumbing.Hash]struct{}) error {
	if _, ok := into[h]; ok {
		return nil
	}
	into[h] = struct{}{}
	tree, err := object.GetTree(store, h)
	if err != nil {
		return fmt.Errorf("load tree %s: %w", h, err)
	}
	for _, e := range tree.Entries {
		if e.Mode.IsFile() {
			into[e.Hash] = struct{}{}
			continue
		}
		if err := collectTree(store, e.Hash, into); err != nil {
			return err
		}
	}
	return nil
}

// sourceRefHash returns the source's value for name, or zero when it has
// none. A v2 listing is filtered to the requested scope, so a ref outside it
// takes another ls-refs.
func (s *syncSession) sourceRefHash(ctx context.Context, name plumbing.ReferenceName) (plumbing.Hash, error) {
	if h, ok := s.sourceRefMap[name]; ok || s.sourceService.Protocol != "v2" {
		return h, nil
	}
	refs, _, err := gitproto.ListSourceRefs(ctx, s.sourceConn, "v2", []string{name.String()})
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("list source %s: %w", name, err)
	}
	return gitproto.RefHashMap(refs)[name], nil
}

// readTargetNotes fetches the target's refs/notes/sha256-origin and reads it.
func (s *syncSession) readTargetNotes(ctx context.Context, tip plumbing.Hash) (map[plumbing.Hash]plumbing.Hash, []translate.NoteEntry, error) {
	_, service, err := gitproto.ListSourceRefs(ctx, s.target.conn, s.cfg.ProtocolMode, []string{targetOriginNotesRef.String()})
	if err != nil {
		return nil, nil, fmt.Errorf("list target %s: %w", targetOriginNotesRef, err)
	}
	store := memory.NewStorage(memory.WithObjectFormat(formatcfg.SHA1))
	desired := map[plumbing.ReferenceName]gitproto.DesiredRef{
		targetOriginNotesRef: {SourceRef: targetOriginNotesRef, TargetRef: targetOriginNotesRef, SourceHash: tip},
	}
	if err := service.FetchToStore(ctx, store, s.target.conn, desired, nil); err != nil {
		return nil, nil, fmt.Errorf("fetch target %s: %w", targetOriginNotesRef, err)
	}
	values, entries, err := translate.ReadHashNotes(store, tip)
	if err != nil {
		return nil, nil, fmt.Errorf("read target %s: %w", targetOriginNotesRef, err)
	}
	return values, entries, nil
}

func sortedRefNames(refs map[plumbing.ReferenceName]planner.DesiredRef) []plumbing.ReferenceName {
	names := make([]plumbing.ReferenceName, 0, len(refs))
	for name := range refs {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

