func (s *syncSession) translating() bool {
	if s.target == nil {
		return false
	}
	return s.sourceService.ObjectFormat() == formatcfg.SHA256 &&
		effectiveObjectFormat(gitproto.AdvRefsObjectFormat(s.target.adv)) == formatcfg.SHA1
